<template><div class="app-container"><el-alert title="该页面只显示配置就绪状态，不返回任何密钥明文。三诺公钥仅保存在服务端部署配置中。" type="warning" :closable="false" style="margin-bottom:16px"/><el-descriptions v-loading="loading" :column="2" border><el-descriptions-item label="设备回调">{{yes(data.callbackEnabled)}}</el-descriptions-item><el-descriptions-item label="回调密钥已配置">{{yes(data.callbackSecretConfigured)}}</el-descriptions-item><el-descriptions-item label="健康数据加密密钥">{{yes(data.encryptionKeyConfigured)}}</el-descriptions-item><el-descriptions-item label="允许明文兼容">{{yes(data.plaintextAllowed)}}</el-descriptions-item><el-descriptions-item label="同步自动重试">{{yes(data.syncAutoRetryEnabled)}}</el-descriptions-item><el-descriptions-item label="数据保留天数">{{data.retentionDays===0?'未启用自动清理':data.retentionDays}}</el-descriptions-item><el-descriptions-item label="归档策略">{{yes(data.archiveEnabled)}}</el-descriptions-item><el-descriptions-item label="三诺 AppId">{{yes(data.sinocareAppIdConfigured)}}</el-descriptions-item><el-descriptions-item label="三诺 H5 授权地址">{{yes(data.sinocareAuthorizationH5UrlConfigured)}}</el-descriptions-item><el-descriptions-item label="三诺公钥">{{yes(data.sinocarePublicKeyConfigured)}}</el-descriptions-item></el-descriptions><el-button style="margin-top:16px" type="primary" @click="load">刷新</el-button></div></template><script>import{getJkHealthIntegrationStatus}from'@/api/jkBusiness';export default{data(){return{data:{},loading:false}},created(){this.load()},methods:{yes(v){return v?'已启用/已配置':'未启用/未配置'},load(){this.loading=true;getJkHealthIntegrationStatus().then(r=>this.data=(r&&r.data)||r||{}).finally(()=>this.loading=false)}}}</script>
